catch {
  return await ort.InferenceSession.create(model, { ...options, executionProviders: ['wasm'] })
}

for node in model.graph.node:
    if node.op_type == "MaxPool":
        for attr in node.attribute:
            if attr.name == "ceil_mode" and attr.i == 1:
                attr.i = 0

export function estimateResultBytes(width: number, height: number, scale: 1 | 2 | 4): number {
  return width * height * scale * scale * 4
}

// A lone image always fits, so the single-image flow keeps working for huge outputs
export function fitsMemoryBudget(heldBytes: number, estimatedBytes: number, budget = BATCH_MEMORY_BUDGET_BYTES): boolean {
  return heldBytes === 0 || heldBytes + estimatedBytes <= budget
}
